// terminalSize --> largeur/hauteur du terminal (ioctl TIOCGWINSZ), 80x24 si indisponible.
type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func terminalSize() (int, int) {
	ws := &winsize{}
	ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	if int(ret) == -1 || ws.Col == 0 || ws.Row == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

// resampleGrid --> ré-échantillonne une grille de caractères (plus proche voisin) vers targetW x targetH.
func resampleGrid(art string, targetW, targetH int) []string {
	rows := strings.Split(strings.TrimRight(art, "\n"), "\n")
	srcH := len(rows)
	if srcH == 0 || targetW <= 0 || targetH <= 0 {
		return rows
	}
	srcW := len(rows[0])

	out := make([]string, targetH)
	for y := 0; y < targetH; y++ {
		srcY := y * srcH / targetH
		if srcY >= srcH {
			srcY = srcH - 1
		}
		row := rows[srcY]
		line := make([]byte, targetW)
		for x := 0; x < targetW; x++ {
			srcX := x * srcW / targetW
			if srcX >= srcW {
				srcX = srcW - 1
			}
			if srcX < len(row) {
				line[x] = row[srcX]
			} else {
				line[x] = ' '
			}
		}
		out[y] = string(line)
	}
	return out
}

// screenCell --> un caractère + sa couleur, à une position de l'écran composé.
type screenCell struct {
	ch    rune
	color [3]int
	bold  bool
}

// buildScreen --> grille targetW x targetH à partir des caractères/couleurs du temple.
func buildScreen(chars, colors []string, targetW, targetH int) [][]screenCell {
	screen := make([][]screenCell, targetH)
	for y := 0; y < targetH; y++ {
		screen[y] = make([]screenCell, targetW)
		for x := 0; x < targetW; x++ {
			cell := screenCell{ch: ' '}
			if y < len(chars) && x < len(chars[y]) {
				cell.ch = rune(chars[y][x])
			}
			if y < len(colors) && x < len(colors[y]) {
				idx := int(colors[y][x]) - 33
				if idx >= 0 && idx < len(templePalette) {
					cell.color = templePalette[idx]
				}
			}
			screen[y][x] = cell
		}
	}
	return screen
}

// scaleArt --> agrandit un bloc ASCII (répétition de chaque caractère/ligne) d'un facteur donné.
func scaleArt(art string, factor int) []string {
	lines := strings.Split(art, "\n")
	out := make([]string, 0, len(lines)*factor)
	for _, line := range lines {
		var b strings.Builder
		for _, r := range line {
			b.WriteString(strings.Repeat(string(r), factor))
		}
		scaled := b.String()
		for i := 0; i < factor; i++ {
			out = append(out, scaled)
		}
	}
	return out
}

// overlayText --> centre des lignes de texte par-dessus l'écran (les espaces laissent voir le fond),
// chaque ligne avec sa propre couleur, en gras pour ressortir sur l'animation.
func overlayText(screen [][]screenCell, lines []string, colors [][3]int, rowOffset int) {
	h := len(screen)
	if h == 0 {
		return
	}
	w := len(screen[0])
	startRow := (h-len(lines))/2 + rowOffset

	for i, line := range lines {
		row := startRow + i
		if row < 0 || row >= h {
			continue
		}
		runes := []rune(line)
		startCol := (w - len(runes)) / 2
		for j, r := range runes {
			col := startCol + j
			if col < 0 || col >= w || r == ' ' {
				continue
			}
			screen[row][col] = screenCell{ch: r, color: colors[i], bold: true}
		}
	}
}

// dimRegion --> assombrit un rectangle de l'écran (halo derrière le texte pour le faire ressortir).
func dimRegion(screen [][]screenCell, top, left, width, height int, factor float64) {
	h := len(screen)
	if h == 0 {
		return
	}
	w := len(screen[0])
	for y := top; y < top+height; y++ {
		if y < 0 || y >= h {
			continue
		}
		for x := left; x < left+width; x++ {
			if x < 0 || x >= w {
				continue
			}
			c := &screen[y][x].color
			c[0] = int(float64(c[0]) * factor)
			c[1] = int(float64(c[1]) * factor)
			c[2] = int(float64(c[2]) * factor)
		}
	}
}

// renderScreen --> transforme la grille composée en chaîne ANSI (24 bits), un code couleur par
// groupe de cases consécutives de même couleur (pour rester léger à l'affichage).
func renderScreen(screen [][]screenCell) string {
	return renderScreenPadded(screen, "")
}

// renderScreenPadded --> comme renderScreen, avec une marge gauche fixe sur chaque ligne (pour
// centrer une grille plus étroite que le terminal, ex. la carte).
func renderScreenPadded(screen [][]screenCell, left string) string {
	var b strings.Builder
	lastColor := [3]int{-1, -1, -1}
	lastBold := false
	for _, row := range screen {
		b.WriteString(left)
		for _, cell := range row {
			if cell.color != lastColor || cell.bold != lastBold {
				if cell.bold {
					fmt.Fprintf(&b, "\033[0;1;38;2;%d;%d;%dm", cell.color[0], cell.color[1], cell.color[2])
				} else {
					fmt.Fprintf(&b, "\033[0;38;2;%d;%d;%dm", cell.color[0], cell.color[1], cell.color[2])
				}
				lastColor, lastBold = cell.color, cell.bold
			}
			b.WriteRune(cell.ch)
		}
		b.WriteString("\r\n") // mode brut --> pas de conversion auto \n en retour chariot
	}
	b.WriteString("\033[0m")
	return b.String()
}

// renderScreenBG --> comme renderScreenPadded, mais remplit chaque case avec une couleur de FOND
// (pas un caractère "█") : la case occupe toute la cellule du terminal, donc jamais de fine ligne
// visible entre les rangées (contrairement à un glyphe plein, qui dépend de la police/l'espacement
// des lignes du terminal). Utilisé pour la carte (blocs de couleur pleins).
func renderScreenBG(screen [][]screenCell, left string) string {
	var b strings.Builder
	for _, row := range screen {
		b.WriteString(left)
		lastColor := [3]int{-1, -1, -1}
		for _, cell := range row {
			if cell.color != lastColor {
				fmt.Fprintf(&b, "\033[48;2;%d;%d;%dm", cell.color[0], cell.color[1], cell.color[2])
				lastColor = cell.color
			}
			b.WriteByte(' ')
		}
		b.WriteString("\033[0m\r\n")
	}
	return b.String()
}

// animatedMenu --> écran plein temple animé, avec un bloc de titre et des options sélectionnables
// aux flèches + Entrée (surlignées en doré). Retourne l'index choisi, -1 si le joueur ferme le flux.
func animatedMenu(title []string, options []string) int {
	targetW, targetH := terminalSize()
	targetH -= 2 // marge de sécurité pour ne jamais dépasser la hauteur visible (sinon ça scrolle)
	if targetH < 15 {
		targetH = 15
	}

	white := [3]int{255, 250, 240}
	gold := [3]int{255, 195, 90}
	dim := [3]int{225, 215, 205}

	selected := 0

	// plage où le mouvement de la caméra est réellement visible (avant/après : quasi statique).
	const rangeStart, rangeEnd = 10, 110
	step := rangeStart
	direction := 1
	ticker := time.NewTicker(100 * time.Millisecond) // rythme d'origine de la vidéo (10 fps)
	defer ticker.Stop()

	fmt.Print("\033[H\033[2J") // un seul vrai nettoyage, au départ

	draw := func() {
		overlay := make([]string, 0, len(title)+len(options)+1)
		colors := make([][3]int, 0, len(title)+len(options)+1)
		for _, l := range title {
			overlay = append(overlay, l)
			colors = append(colors, white)
		}
		overlay = append(overlay, "")
		colors = append(colors, white)

		for i, opt := range options {
			if i == selected {
				overlay = append(overlay, "▶  "+opt)
				colors = append(colors, gold)
			} else {
				overlay = append(overlay, "   "+opt)
				colors = append(colors, dim)
			}
		}

		charGrid := resampleGrid(templeFrames[step], targetW, targetH)
		colorGrid := resampleGrid(templeColors[step], targetW, targetH)
		screen := buildScreen(charGrid, colorGrid, targetW, targetH)

		maxWidth := 0
		for _, l := range overlay {
			if n := len([]rune(l)); n > maxWidth {
				maxWidth = n
			}
		}
		boxTop := (targetH-len(overlay))/2 - 1
		boxLeft := (targetW-maxWidth)/2 - 4
		dimRegion(screen, boxTop, boxLeft, maxWidth+8, len(overlay)+2, 0.25)

		overlayText(screen, overlay, colors, 0)

		fmt.Print("\033[H") // réécrit par-dessus, sans effacer --> pas de clignotement
		fmt.Print(renderScreen(screen))
	}
	draw()

	for {
		select {
		case key, ok := <-arrowChan:
			if !ok {
				return -1
			}
			switch key {
			case "up":
				selected = (selected - 1 + len(options)) % len(options)
				draw()
			case "down":
				selected = (selected + 1) % len(options)
				draw()
			case "enter":
				return selected
			case "quit":
				return -1
			}
		case <-ticker.C:
			step += direction
			if step >= rangeEnd {
				step, direction = rangeEnd, -1
			} else if step <= rangeStart {
				step, direction = rangeStart, 1
			}
			draw()
		}
	}
}

// Écran titre : startScreen --> logo + vidéo du temple animée, boutons Jouer/Quitter.
func startScreen() bool {
	logoScale := 1
	if w, _ := terminalSize(); w >= 140 {
		logoScale = 2
	}
	logo := scaleArt(logoArt, logoScale)

	title := make([]string, 0, len(logo)+2)
	title = append(title, logo...)
	title = append(title, "", subtitleText)

	choice := animatedMenu(title, []string{"Jouer", "Quitter"})
	return choice == 0
}
